import java.util.Scanner;

public class Main {
    static final int N = 505;
    static int[][] C = new int[N][N];
    static long[] f = new long[N];
    static long[] g = new long[N];
    static long[][] ff = new long[N][N];
    static long[][] gg = new long[N][N];

    static void add(int[] x, int y, int mod) {
        x[0] += y;
        if (x[0] >= mod) x[0] -= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        // Compute binomial coefficients
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % mod;
            }
        }

        f[0] = 1;
        g[0] = 0;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long val1 = (f[j - 1] * f[i - j]) % mod;
                long val2 = (long) C[i - 1][j - 1] * (i + 1) % mod;
                add(new int[]{(int) f[i]}, (int) (val1 * val2 % mod), mod);

                long tempG1 = (g[j - 1] * f[i - j]) % mod;
                long tempG2 = (g[i - j] * f[j - 1]) % mod;
                long tempG3 = 0;
                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                }
                long tempG4 = (long) f[j - 1] * f[i - j] % mod * s % mod;

                g[i] = (int) ((g[i] + tempG1 * C[i - 1][j - 1] % mod * (i + 1) % mod) % mod);
                g[i] = (int) ((g[i] + tempG2 * C[i - 1][j - 1] % mod * (i + 1) % mod) % mod);
                g[i] = (int) ((g[i] + tempG4) % mod);
            }
        }

        ff[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == i) {
                    ff[i][j] = f[i];
                    gg[i][j] = g[i];
                    break;
                }
                ff[i][j] = ff[i - 1][j];
                gg[i][j] = gg[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    long valF = (ff[i - k - 1][j - k] * f[k]) % mod;
                    long valC = C[j][k];
                    add(new int[]{(int) ff[i][j]}, (int) (valF * valC % mod), mod);

                    long valG1 = (ff[i - k - 1][j - k] * g[k]) % mod;
                    long valG2 = (gg[i - k - 1][j - k] * f[k]) % mod;
                    long valG3 = (gg[i - k - 1][j - k] * g[k]) % mod;

                    add(new int[]{(int) gg[i][j]}, (int) (valG1 * valC % mod), mod);
                    add(new int[]{(int) gg[i][j]}, (int) (valG2 * valC % mod), mod);
                    add(new int[]{(int) gg[i][j]}, (int) (valG3 * valC % mod), mod);
                }
            }
        }

        System.out.println(gg[n][m]);
        sc.close();
    }
}
